CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE IF NOT EXISTS organizations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL CHECK(length(name) BETWEEN 1 AND 120), slug text NOT NULL UNIQUE, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS users (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES organizations(id) ON DELETE CASCADE, email text NOT NULL, name text NOT NULL CHECK(length(name) BETWEEN 1 AND 120), password_hash text NOT NULL, role text NOT NULL DEFAULT 'member' CHECK(role IN ('owner','admin','member')), active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(organization_id,email));
CREATE INDEX IF NOT EXISTS users_org_idx ON users(organization_id);
CREATE TABLE IF NOT EXISTS refresh_sessions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE, token_hash text NOT NULL UNIQUE, expires_at timestamptz NOT NULL, revoked_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS objectives (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES organizations(id) ON DELETE CASCADE, title text NOT NULL CHECK(length(title) BETWEEN 1 AND 140), description text NOT NULL DEFAULT '', team text NOT NULL DEFAULT 'General', owner_id uuid REFERENCES users(id) ON DELETE SET NULL, due_date date, status text NOT NULL DEFAULT 'on_track' CHECK(status IN ('on_track','at_risk','behind','complete')), created_by uuid REFERENCES users(id) ON DELETE SET NULL, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS objectives_org_idx ON objectives(organization_id);
CREATE TABLE IF NOT EXISTS key_results (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES organizations(id) ON DELETE CASCADE, objective_id uuid NOT NULL REFERENCES objectives(id) ON DELETE CASCADE, title text NOT NULL CHECK(length(title) BETWEEN 1 AND 140), metric_type text NOT NULL DEFAULT 'number' CHECK(metric_type IN ('number','percent','currency')), current_value numeric(14,3) NOT NULL DEFAULT 0 CHECK(current_value>=0), target_value numeric(14,3) NOT NULL CHECK(target_value>0), owner_id uuid REFERENCES users(id) ON DELETE SET NULL, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS key_results_org_objective_idx ON key_results(organization_id,objective_id);
CREATE TABLE IF NOT EXISTS check_ins (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES organizations(id) ON DELETE CASCADE, key_result_id uuid NOT NULL REFERENCES key_results(id) ON DELETE CASCADE, user_id uuid REFERENCES users(id) ON DELETE SET NULL, value numeric(14,3) NOT NULL CHECK(value>=0), note text NOT NULL CHECK(length(note) BETWEEN 1 AND 1000), created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS check_ins_org_created_idx ON check_ins(organization_id,created_at DESC);
CREATE TABLE IF NOT EXISTS notification_preferences (organization_id uuid NOT NULL REFERENCES organizations(id) ON DELETE CASCADE, user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE, channel text NOT NULL CHECK(channel IN ('email','slack','teams','in_app')), enabled boolean NOT NULL DEFAULT false, destination text, updated_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(user_id,channel));
CREATE TABLE IF NOT EXISTS integrations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES organizations(id) ON DELETE CASCADE, provider text NOT NULL CHECK(provider IN ('slack','teams')), encrypted_secret text NOT NULL, destination text, enabled boolean NOT NULL DEFAULT false, created_by uuid REFERENCES users(id) ON DELETE SET NULL, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(organization_id,provider));
CREATE TABLE IF NOT EXISTS reminder_deliveries (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES organizations(id) ON DELETE CASCADE, user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE, reminder_type text NOT NULL, period_key text NOT NULL, status text NOT NULL DEFAULT 'queued' CHECK(status IN ('queued','sent','failed')), last_error text, created_at timestamptz NOT NULL DEFAULT now(), sent_at timestamptz, UNIQUE(user_id,reminder_type,period_key));
CREATE INDEX IF NOT EXISTS reminder_due_idx ON reminder_deliveries(status,created_at);
CREATE TABLE IF NOT EXISTS audit_events (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES organizations(id) ON DELETE CASCADE, actor_id uuid REFERENCES users(id) ON DELETE SET NULL, action text NOT NULL, entity_type text NOT NULL, entity_id uuid, metadata jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now());
